@androidx.media3.common.util.UnstableApi
public class DownloadCenterActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());private final ArrayList<DownloadHistory.Entry> shown=new ArrayList<>();private int filter,type,order;private String query="";private boolean wasActive,visible;private String snapshot="";private TextView summary;private Rows adapter;private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 private final Runnable tick=new Runnable(){public void run(){if(!visible)return;refresh();handler.removeCallbacks(this);if(MediaDownloadService.activeDownload)handler.postDelayed(this,1000);}};
 private final SharedPreferences.OnSharedPreferenceChangeListener changes=(prefs,key)->{if(visible&&"data".equals(key)){handler.removeCallbacks(tick);handler.post(tick);}};
 private void refilter(){snapshot="\u0000";refresh();}
 private void typeOptions(){new AlertDialog.Builder(this).setTitle("Tipo de arquivo").setSingleChoiceItems(new String[]{"Todos os tipos","Somente áudio","Somente vídeo"},type,(d,n)->{type=n;refilter();d.dismiss();}).setNegativeButton("Fechar",null).show();}
 private void orderOptions(){new AlertDialog.Builder(this).setTitle("Ordenar downloads").setSingleChoiceItems(new String[]{"Mais recentes","Mais antigos","Nome A–Z","Maior tamanho transferido"},order,(d,n)->{order=n;refilter();d.dismiss();}).setNegativeButton("Fechar",null).show();}
 private static String normalized(String text){return Normalizer.normalize(text,Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).trim();}
 private void share(DownloadHistory.Entry entry){worker.execute(()->{try{Uri uri=Uri.parse(entry.uri);if(!"content".equals(uri.getScheme()))throw new IllegalArgumentException();try(android.content.res.AssetFileDescriptor file=getContentResolver().openAssetFileDescriptor(uri,"r")){if(file==null)throw new java.io.IOException();}runOnUiThread(()->{if(!visible||isDestroyed())return;try{Intent send=new Intent(Intent.ACTION_SEND).setType(MediaDownloadService.mime(entry.format)).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("Arquivo do Onda",uri));startActivity(Intent.createChooser(send,"Compartilhar arquivo"));}catch(Exception e){shareError();}});}catch(Exception e){runOnUiThread(()->{if(visible&&!isDestroyed())shareError();});}});}
 private void shareError(){new AlertDialog.Builder(this).setMessage("Arquivo indisponível. Confira se ele existe e se o acesso à pasta está autorizado.").setPositiveButton("OK",null).show();}

 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){filter=state.getInt("filter",0);type=state.getInt("type",0);order=state.getInt("order",0);query=state.getString("query","");}LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Central de downloads",20,Ui.TEXT);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));bar.addView(Ui.menuButton(this,"Menu da central",v->Ui.menu(this,v,new String[]{"Tipo de arquivo","Ordenar downloads","Novo download","Arquivos do Onda","Conversor local","Escolher pasta do Onda",OndaFolders.enabled(this)?"Pedir local a cada download":"Usar pasta do Onda","Cancelar operação","Limpar histórico finalizado"},new String[]{"Tipo de arquivo","Ordenar downloads","Novo download","Arquivos do Onda","Conversor local","Escolher pasta do Onda","Alterar local dos próximos downloads","Cancelar operação","Limpar registros, sem apagar arquivos"},new Runnable[]{this::typeOptions,this::orderOptions,()->startActivity(new Intent(this,DownloadsActivity.class)),()->startActivity(new Intent(this,OndaFilesActivity.class)),()->startActivity(new Intent(this,LocalConverterActivity.class)),this::chooseFolder,this::toggleFolder,this::cancel,this::clear})),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));root.addView(bar);
  Spinner tabs=new Spinner(this);tabs.setContentDescription("Filtrar histórico de downloads");ArrayAdapter<String> options=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Todos","Em andamento","Concluídos","Falhas e interrupções"});tabs.setAdapter(options);tabs.setSelection(filter);root.addView(tabs,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));tabs.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){filter=position;refilter();}});
  EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(16);search.setHint("Buscar nome, formato ou origem");search.setContentDescription("Buscar no histórico de downloads");search.setTextColor(Ui.TEXT);search.setHintTextColor(Ui.MUTED);search.setInputType(android.text.InputType.TYPE_CLASS_TEXT);search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);search.setText(query);search.setSelection(search.length());search.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);search.clearFocus();return true;}return false;});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence text,int start,int before,int count){query=text.toString();refilter();}public void afterTextChanged(Editable e){}});root.addView(search,new LinearLayout.LayoutParams(-1,Ui.dp(this,52)));
  summary=Ui.text(this,"",13,Ui.MUTED);root.addView(summary);ListView list=new ListView(this);list.setDivider(null);adapter=new Rows();list.setAdapter(adapter);list.setOnItemClickListener((p,v,index,id)->actions(shown.get(index)));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));TextView note=Ui.text(this,"Até 200 registros locais. Menu: tipo e ordenação. Toque em um arquivo para abrir, compartilhar ou tentar novamente.",12,Ui.MUTED);root.addView(note);if(getIntent().getBooleanExtra("choose_folder",false)&&state==null)handler.post(this::chooseFolder);
 }
 private void refresh(){if(summary==null||adapter==null)return;if(wasActive&&!MediaDownloadService.activeDownload)DownloadHistory.settle(this,"interrupted","A operação anterior foi encerrada. Tente novamente para reanalisar o link.");wasActive=MediaDownloadService.activeDownload;String data=getSharedPreferences(DownloadHistory.PREF,0).getString("data","");if(data.equals(snapshot))return;snapshot=data;List<DownloadHistory.Entry> all=DownloadHistory.read(this);shown.clear();int active=0,done=0,failed=0;for(DownloadHistory.Entry e:all){if(e.active())active++;else if(e.state.equals("done"))done++;else failed++;boolean stateMatch=filter==0||filter==1&&e.active()||filter==2&&e.state.equals("done")||filter==3&&!e.active()&&!e.state.equals("done");boolean typeMatch=type==0||type==1&&!e.format.equals("mp4")||type==2&&e.format.equals("mp4");boolean searchMatch=normalized(e.title+" "+e.format+" "+e.source).contains(normalized(query));if(stateMatch&&typeMatch&&searchMatch)shown.add(e);}Comparator<DownloadHistory.Entry> compare=order==1?Comparator.comparingLong(e->e.time):order==2?Comparator.comparing(e->normalized(e.title)):order==3?Comparator.<DownloadHistory.Entry>comparingLong(e->e.bytes).reversed():Comparator.<DownloadHistory.Entry>comparingLong(e->e.time).reversed();Collections.sort(shown,compare);summary.setText(all.isEmpty()?"Nenhum arquivo registrado ainda.":shown.size()+" de "+all.size()+" registros • "+(type==0?"todos os tipos":type==1?"áudio":"vídeo")+" • "+new String[]{"mais recentes","mais antigos","nome A–Z","maior tamanho"}[order]+"\n"+active+" em andamento • "+done+" concluídos • "+failed+" com falha/interrupção");adapter.notifyDataSetChanged();}
 private void actions(DownloadHistory.Entry e){ArrayList<String> names=new ArrayList<>();ArrayList<Runnable> actions=new ArrayList<>();if(e.state.equals("done")&&!e.uri.isEmpty()){names.add("Abrir arquivo");actions.add(()->open(e));if(e.uri.startsWith("content:")){names.add("Compartilhar arquivo");actions.add(()->share(e));}}if(e.retryable()){names.add("Tentar novamente");actions.add(()->startActivity(new Intent(this,DownloadsActivity.class).putExtra("retry_link",e.source)));}if(e.active()){names.add("Cancelar operação");actions.add(this::cancel);}names.add("Copiar detalhes");actions.add(()->{String detail=e.title+"\n"+DownloadHistory.label(e.state)+"\n"+e.detail;((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Download Onda",detail));Toast.makeText(this,"Detalhes copiados",Toast.LENGTH_SHORT).show();});new AlertDialog.Builder(this).setTitle(e.title).setItems(names.toArray(new String[0]),(d,n)->actions.get(n).run()).setNegativeButton("Fechar",null).show();}
 private void open(DownloadHistory.Entry e){try{Uri uri=Uri.parse(e.uri);if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme()))throw new IllegalArgumentException();Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,MediaDownloadService.mime(e.format)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).setClass(this,e.format.equals("mp4")?VideoActivity.class:MainActivity.class);startActivity(i);}catch(Exception error){new AlertDialog.Builder(this).setMessage("Não foi possível abrir. Confira se o arquivo existe e se o acesso à pasta continua permitido.").setPositiveButton("OK",null).show();}}
 private void cancel(){if(MediaDownloadService.activeDownload)new AlertDialog.Builder(this).setTitle("Cancelar operação?").setMessage("Arquivos já concluídos serão mantidos.").setNegativeButton("Voltar",null).setPositiveButton("Cancelar operação",(d,w)->startService(new Intent(this,MediaDownloadService.class).setAction("cancel"))).show();else Toast.makeText(this,"Nenhuma operação em andamento",Toast.LENGTH_SHORT).show();}
 private void clear(){new AlertDialog.Builder(this).setTitle("Limpar histórico finalizado?").setMessage("Remove os registros concluídos, falhos e cancelados. Os arquivos salvos permanecem na pasta escolhida.").setNegativeButton("Voltar",null).setPositiveButton("Limpar histórico",(d,w)->{DownloadHistory.clearFinished(this);snapshot="";refresh();}).show();}
 private final class Rows extends BaseAdapter {
  public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}
  public View getView(int p,View reusable,android.view.ViewGroup parent){LinearLayout box;if(reusable instanceof LinearLayout)box=(LinearLayout)reusable;else{box=new LinearLayout(DownloadCenterActivity.this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(Ui.dp(DownloadCenterActivity.this,12),Ui.dp(DownloadCenterActivity.this,12),Ui.dp(DownloadCenterActivity.this,12),Ui.dp(DownloadCenterActivity.this,12));box.addView(Ui.text(DownloadCenterActivity.this,"",16,Ui.TEXT));box.addView(Ui.text(DownloadCenterActivity.this,"",12,Ui.CYAN));box.addView(new ProgressBar(DownloadCenterActivity.this,null,android.R.attr.progressBarStyleHorizontal),new LinearLayout.LayoutParams(-1,Ui.dp(DownloadCenterActivity.this,18)));box.addView(Ui.text(DownloadCenterActivity.this,"",12,Ui.MUTED));Ui.card(box,false);}DownloadHistory.Entry e=shown.get(p);((TextView)box.getChildAt(0)).setText(e.title);((TextView)box.getChildAt(1)).setText(DownloadHistory.label(e.state)+" • "+e.format.toUpperCase(Locale.ROOT)+" • "+android.text.format.DateFormat.format("dd/MM HH:mm",e.time));ProgressBar progress=(ProgressBar)box.getChildAt(2);progress.setVisibility(e.state.equals("running")?View.VISIBLE:View.GONE);progress.setIndeterminate(e.expected<=0);progress.setMax(100);if(e.expected>0)progress.setProgress((int)Math.min(100,e.bytes*100/e.expected));String bytes=e.bytes>0?"\nTrecho transferido: "+android.text.format.Formatter.formatShortFileSize(DownloadCenterActivity.this,e.bytes)+(e.expected>0?" de "+android.text.format.Formatter.formatShortFileSize(DownloadCenterActivity.this,e.expected):""):"";((TextView)box.getChildAt(3)).setText(e.detail+bytes);return box;}
 }
 private void chooseFolder(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),710);}catch(Exception e){Toast.makeText(this,"Seletor de pastas indisponível",Toast.LENGTH_LONG).show();}}
 private void toggleFolder(){if(getSharedPreferences(OndaFolders.PREF,0).getString("tree","").isEmpty()){chooseFolder();return;}boolean enabled=OndaFolders.enabled(this);getSharedPreferences(OndaFolders.PREF,0).edit().putBoolean("enabled",!enabled).apply();Toast.makeText(this,enabled?"O Android pedirá o local de cada download":"Próximos downloads em Onda/Áudios ou Onda/Vídeos",Toast.LENGTH_LONG).show();}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=710||result!=RESULT_OK||data==null||data.getData()==null)return;Uri tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}worker.execute(()->{String message;try{OndaFolders.configure(this,tree);message="Pasta configurada: Onda/Áudios e Onda/Vídeos. Novos downloads usarão essas pastas.";}catch(Exception e){message="Não foi possível configurar. Selecione uma pasta gravável pelo Android.";}String resultMessage=message;runOnUiThread(()->{if(!isDestroyed())new AlertDialog.Builder(this).setTitle("Pasta do Onda").setMessage(resultMessage).setPositiveButton("OK",null).show();});});}
 @Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putInt("filter",filter);state.putInt("type",type);state.putInt("order",order);state.putString("query",query);}
 @Override public void onStart(){super.onStart();visible=true;getSharedPreferences(DownloadHistory.PREF,0).registerOnSharedPreferenceChangeListener(changes);wasActive=MediaDownloadService.activeDownload;if(!wasActive)DownloadHistory.settle(this,"interrupted","A operação anterior foi encerrada. Tente novamente para reanalisar o link.");snapshot="\u0000";handler.post(tick);}@Override public void onStop(){visible=false;getSharedPreferences(DownloadHistory.PREF,0).unregisterOnSharedPreferenceChangeListener(changes);handler.removeCallbacks(tick);super.onStop();}
}
